#!/usr/bin/env python3
"""Controller-triggered show actions for PuddleDuck.

The trigger engine runs on the body Orin and consumes normal ``PuddleJoy``
``ControllerEvent`` objects.  It therefore sees named buttons from RC, USB,
Bluetooth, and virtual controllers without interpreting the UDP state stream.
"""

from __future__ import annotations

import dataclasses
import queue
import re
import shlex
import threading
import time
from pathlib import Path
from typing import Any, Callable, Dict, List, Mapping, Optional, Sequence, Tuple

import yaml


BUTTON_PHASES = ("press", "release", "change", "any")
ACTION_KEYS = {"play", "play_from", "quack", "pdplay", "pdrelax"}
AUDIO_TARGETS = {"head", "body"}
SOUND_EXTENSIONS = {".wav", ".mp3", ".ogg", ".oga", ".opus", ".flac", ".m4a", ".aac"}
SOUND_COMPONENT_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._ ()+-]{0,159}$")
PDPLAY_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._+-]{0,79}$")


class TriggerConfigError(ValueError):
    pass


def _as_list(value: Any) -> List[Any]:
    if value is None:
        return []
    if isinstance(value, list):
        return value
    if isinstance(value, tuple):
        return list(value)
    return [value]


def _bool(value: Any, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value).strip().casefold()
    if text in {"1", "true", "yes", "on", "enabled"}:
        return True
    if text in {"0", "false", "no", "off", "disabled"}:
        return False
    return default


def _float(value: Any, default: float) -> float:
    try:
        return float(value)
    except Exception:
        return float(default)


def _target(value: Any, default: str = "head") -> str:
    target = str(value or default).strip().lower()
    if target not in AUDIO_TARGETS:
        raise TriggerConfigError("sound target must be 'head' or 'body'")
    return target


def _sound_path(value: Any, *, require_file: bool) -> str:
    text = str(value or "").strip().replace("\\", "/")
    candidate = Path(text)
    if not text or candidate.is_absolute() or any(part in ("", ".", "..") for part in candidate.parts):
        raise TriggerConfigError("sound paths must be relative and may not contain '.' or '..'")
    if len(candidate.parts) > 12:
        raise TriggerConfigError("sound path has too many directory levels")
    for component in candidate.parts:
        if not SOUND_COMPONENT_RE.fullmatch(component):
            raise TriggerConfigError(f"unsupported sound path component: {component!r}")
    if require_file and candidate.suffix.lower() not in SOUND_EXTENSIONS:
        raise TriggerConfigError("play action must name WAV, MP3, Ogg, Opus, FLAC, M4A, or AAC audio")
    return candidate.as_posix()


def _pdplay_name(value: Any) -> str:
    name = str(value or "").strip()
    if not name or not PDPLAY_NAME_RE.fullmatch(name) or "/" in name or "\\" in name:
        raise TriggerConfigError("pdplay action must name one pose/script without path separators")
    return name


def _normalize_action(action: Any, *, default_target: str) -> Dict[str, Any]:
    """Normalize one user action into a strict internal mapping."""
    key = ""
    value: Any = None
    if isinstance(action, Mapping):
        present = [name for name in ACTION_KEYS if name in action]
        if len(present) != 1:
            raise TriggerConfigError(
                "each trigger action mapping must contain exactly one of "
                + ", ".join(sorted(ACTION_KEYS))
            )
        key = present[0]
        value = action[key]
    else:
        try:
            parts = shlex.split(str(action))
        except ValueError as exc:
            raise TriggerConfigError(f"invalid trigger action {action!r}: {exc}") from exc
        if not parts:
            raise TriggerConfigError("trigger action may not be empty")
        key = parts[0].strip().lower()
        if key not in ACTION_KEYS:
            raise TriggerConfigError(
                f"unsupported trigger action {key!r}; use "
                + ", ".join(sorted(ACTION_KEYS))
            )
        if key == "pdrelax":
            if len(parts) != 1:
                raise TriggerConfigError("pdrelax action does not take an argument")
            value = True
        elif len(parts) < 2:
            raise TriggerConfigError(f"{key} action is missing its argument")
        elif key in {"play", "play_from", "pdplay"}:
            if len(parts) != 2:
                argument = "pose/script name" if key == "pdplay" else "path"
                raise TriggerConfigError(f"{key} action must contain exactly one {argument}")
            value = parts[1]
        else:
            value = " ".join(parts[1:])

    if key == "pdrelax":
        return {"kind": "pdrelax"}

    if key == "pdplay":
        name = value.get("name", value.get("script", value.get("pose", ""))) if isinstance(value, Mapping) else value
        return {"kind": "pdplay", "name": _pdplay_name(name)}

    if key == "quack":
        command = str(value.get("command", "") if isinstance(value, Mapping) else value).strip()
        if not command.startswith("/") or "\n" in command or "\r" in command or "\0" in command:
            raise TriggerConfigError("quack action must be one newline-free QuackHead command beginning with '/'")
        return {"kind": "quack", "command": command}

    if key == "play":
        if isinstance(value, Mapping):
            sound = str(value.get("file", value.get("sound", value.get("name", "")))).strip()
            target = _target(value.get("target"), default_target)
        else:
            sound = str(value).strip()
            target = default_target
        sound = _sound_path(sound, require_file=True)
        return {"kind": "play", "sound": sound, "target": target}

    if isinstance(value, Mapping):
        directory = str(value.get("dir", value.get("directory", ""))).strip()
        target = _target(value.get("target"), default_target)
        recursive = _bool(value.get("recursive"), False)
    else:
        directory = str(value).strip()
        target = default_target
        recursive = False
    directory = _sound_path(directory, require_file=False)
    return {"kind": "play_from", "directory": directory, "target": target, "recursive": recursive}


@dataclasses.dataclass
class Trigger:
    label: str
    selectors: Tuple[Tuple[str, Any], ...]
    phase: str
    actions: Tuple[Dict[str, Any], ...]
    cooldown_s: float
    enabled: bool = True
    last_fire: float = 0.0


@dataclasses.dataclass(frozen=True)
class TriggerEvent:
    name: str
    code: Optional[int]
    pressed: bool
    source: str
    timestamp: float

    @property
    def phase(self) -> str:
        return "press" if self.pressed else "release"


class TriggerDefinition:
    """Parsed, validated trigger document."""

    def __init__(self, document: Mapping[str, Any]):
        if not isinstance(document, Mapping):
            raise TriggerConfigError("duck_triggers.yaml root must be a mapping")
        defaults = document.get("defaults") or {}
        if not isinstance(defaults, Mapping):
            raise TriggerConfigError("duck_triggers.yaml defaults must be a mapping")
        self.default_phase = str(defaults.get("event", "press")).strip().lower()
        if self.default_phase not in BUTTON_PHASES:
            raise TriggerConfigError("defaults.event must be press, release, change, or any")
        self.default_cooldown_s = max(0.0, _float(defaults.get("cooldown_s"), 0.10))
        self.default_target = _target(defaults.get("target"), "head")
        self.triggers: List[Trigger] = []
        self._parse(document.get("triggers") or {})

    @staticmethod
    def selector(value: Any) -> Tuple[str, Any]:
        if isinstance(value, int):
            return ("code", int(value))
        text = str(value or "").strip()
        if not text:
            raise TriggerConfigError("trigger selector may not be empty")
        low = text.casefold()
        if low == "*":
            return ("any", "*")
        if low.startswith("rc:"):
            tail = text.split(":", 1)[1].strip()
            if not tail.isdigit():
                raise TriggerConfigError(f"invalid RC selector {text!r}")
            return ("code", int(tail))
        if low.startswith("kyberpad:") or low.startswith("button:"):
            tail = text.split(":", 1)[1].strip()
            if not tail.isdigit():
                raise TriggerConfigError(f"invalid KyberPad selector {text!r}")
            return ("code", 1000 + int(tail))
        if low.startswith("btn") and text[3:].isdigit():
            return ("code", int(text[3:]))
        if text.isdigit():
            return ("code", int(text))
        return ("name", low)

    def _append(self, label: str, selectors: Sequence[Any], phase: str, actions: Any, cooldown: float, enabled: bool) -> None:
        phase = str(phase or self.default_phase).strip().lower()
        if phase not in BUTTON_PHASES:
            raise TriggerConfigError(f"trigger {label!r} has invalid event {phase!r}")
        normalized = tuple(_normalize_action(item, default_target=self.default_target) for item in _as_list(actions))
        if not normalized:
            raise TriggerConfigError(f"trigger {label!r} has no actions")
        parsed_selectors = tuple(self.selector(item) for item in selectors)
        self.triggers.append(Trigger(label, parsed_selectors, phase, normalized, max(0.0, float(cooldown)), enabled))

    def _parse_one(self, label: str, selectors: Sequence[Any], value: Any) -> None:
        if isinstance(value, Mapping):
            enabled = _bool(value.get("enabled"), True)
            cooldown = max(0.0, _float(value.get("cooldown_s"), self.default_cooldown_s))
            found = False
            if "actions" in value or "action" in value:
                self._append(
                    label,
                    selectors,
                    value.get("on", value.get("event", self.default_phase)),
                    value.get("actions", value.get("action")),
                    cooldown,
                    enabled,
                )
                found = True
            for phase in BUTTON_PHASES:
                if phase in value:
                    self._append(label, selectors, phase, value[phase], cooldown, enabled)
                    found = True
            if found:
                return
            # A one-key action mapping is also valid as the complete trigger value.
            if any(name in value for name in ACTION_KEYS):
                self._append(label, selectors, self.default_phase, value, cooldown, enabled)
                return
            raise TriggerConfigError(f"trigger {label!r} must contain actions or a phase key")
        self._append(label, selectors, self.default_phase, value, self.default_cooldown_s, True)

    def _parse(self, raw: Any) -> None:
        if isinstance(raw, Mapping):
            for key, value in raw.items():
                self._parse_one(str(key), [key], value)
            return
        if isinstance(raw, list):
            for index, item in enumerate(raw):
                if not isinstance(item, Mapping):
                    raise TriggerConfigError(f"triggers[{index}] must be a mapping")
                selectors = item.get("buttons", item.get("button", item.get("trigger")))
                if selectors is None:
                    raise TriggerConfigError(f"triggers[{index}] is missing button/buttons/trigger")
                label = str(item.get("name") or ",".join(str(v) for v in _as_list(selectors)))
                payload = dict(item)
                for key in ("name", "buttons", "button", "trigger"):
                    payload.pop(key, None)
                self._parse_one(label, _as_list(selectors), payload)
            return
        raise TriggerConfigError("duck_triggers.yaml triggers must be a mapping or list")

    def summary(self) -> List[Dict[str, Any]]:
        return [
            {
                "index": index,
                "name": trigger.label,
                "event": trigger.phase,
                "selectors": [str(value) for _kind, value in trigger.selectors],
                "actions": len(trigger.actions),
                "enabled": trigger.enabled,
            }
            for index, trigger in enumerate(self.triggers)
        ]


def parse_trigger_yaml(text: str) -> Tuple[Dict[str, Any], TriggerDefinition]:
    if not isinstance(text, str):
        raise TriggerConfigError("duck_triggers YAML must be text")
    try:
        document = yaml.safe_load(text) or {}
    except yaml.YAMLError as exc:
        mark = getattr(exc, "problem_mark", None)
        where = f" at line {mark.line + 1}, column {mark.column + 1}" if mark is not None else ""
        problem = getattr(exc, "problem", None) or str(exc)
        raise TriggerConfigError(f"invalid duck_triggers YAML{where}: {problem}") from exc
    if not isinstance(document, dict):
        raise TriggerConfigError("duck_triggers.yaml root must be a mapping")
    return document, TriggerDefinition(document)


class DuckTriggerManager:
    """Live-reloadable trigger executor.

    ``play`` and ``play_from`` callbacks receive ``(target, value, recursive)``.
    The QuackHead callback receives one command string.  ``pdplay`` and
    ``pdrelax`` are robot command callbacks backed by the same broker used by
    the web UI.
    """

    def __init__(
        self,
        path: str,
        *,
        play: Callable[[str, str], Any],
        play_from: Callable[[str, str, bool], Any],
        quack: Callable[[str], Any],
        pdplay: Callable[[str], Any],
        pdrelax: Callable[[], Any],
        workers: int = 2,
    ):
        self.path = Path(path).expanduser()
        self._play = play
        self._play_from = play_from
        self._quack = quack
        self._pdplay = pdplay
        self._pdrelax = pdrelax
        self._lock = threading.RLock()
        self._definition = TriggerDefinition({"triggers": {}})
        self._last_error = ""
        self._last_event = ""
        self._last_trigger = ""
        self._fired = 0
        self._queue: "queue.Queue[Tuple[Trigger, TriggerEvent]]" = queue.Queue(maxsize=64)
        self._workers: List[threading.Thread] = []
        for index in range(max(1, int(workers))):
            thread = threading.Thread(target=self._worker, name=f"duck-trigger-{index}", daemon=True)
            thread.start()
            self._workers.append(thread)
        self.reload()

    def reload(self) -> Dict[str, Any]:
        with self._lock:
            try:
                if not self.path.is_file():
                    self._definition = TriggerDefinition({"triggers": {}})
                    self._last_error = ""
                    return {
                        "ok": True,
                        "path": str(self.path),
                        "loaded": 0,
                        "message": "duck_triggers.yaml is absent; no show triggers are configured",
                    }
                text = self.path.read_text(encoding="utf-8")
                _document, definition = parse_trigger_yaml(text)
                self._definition = definition
                self._last_error = ""
                return {
                    "ok": True,
                    "path": str(self.path),
                    "loaded": len(definition.triggers),
                    "message": f"loaded {len(definition.triggers)} trigger(s)",
                }
            except Exception as exc:
                self._definition = TriggerDefinition({"triggers": {}})
                self._last_error = str(exc)
                return {"ok": False, "path": str(self.path), "loaded": 0, "message": str(exc)}

    def status(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "ok": not bool(self._last_error),
                "path": str(self.path),
                "loaded": len(self._definition.triggers),
                "last_error": self._last_error,
                "last_event": self._last_event,
                "last_trigger": self._last_trigger,
                "fired": self._fired,
                "queued": self._queue.qsize(),
            }

    @staticmethod
    def _event(ev: Any) -> Optional[TriggerEvent]:
        try:
            if not bool(ev.is_button_event()):
                return None
        except Exception:
            return None
        if bool(getattr(ev, "initial", False)):
            return None
        gesture = getattr(ev, "gesture", None)
        pressed = True if gesture else bool(getattr(ev, "value", 0))
        name = str(getattr(ev, "name", "") or "").strip()
        number = getattr(ev, "number", None)
        try:
            code = int(number) if number is not None else None
        except Exception:
            code = None
        controller = getattr(ev, "controller", None)
        source = str(
            getattr(controller, "name", None)
            or getattr(controller, "device_name", None)
            or getattr(controller, "device_path", None)
            or "controller"
        )
        return TriggerEvent(name=name, code=code, pressed=pressed, source=source, timestamp=time.time())

    @staticmethod
    def _aliases(event: TriggerEvent) -> set[Tuple[str, Any]]:
        aliases: set[Tuple[str, Any]] = {("name", event.name.casefold()), ("any", "*")}
        if event.code is not None:
            aliases.add(("code", event.code))
            aliases.add(("name", f"btn{event.code}"))
        return aliases

    def fire(self, index_value: Any) -> Dict[str, Any]:
        """Queue one configured trigger explicitly from the web interface.

        Manual execution runs the exact trigger row shown by ``summary()`` and
        bypasses selector/phase matching.  It still updates the trigger's
        cooldown timestamp so an immediately following controller event cannot
        accidentally execute the same actions twice.
        """
        try:
            index = int(index_value)
        except (TypeError, ValueError) as exc:
            raise ValueError("trigger index must be an integer") from exc

        with self._lock:
            triggers = self._definition.triggers
            if index < 0 or index >= len(triggers):
                raise ValueError("configured trigger no longer exists; reload the Triggers page")
            trigger = triggers[index]
            if not trigger.enabled:
                raise ValueError(f"trigger {trigger.label!r} is disabled")
            trigger.last_fire = time.monotonic()
            event = TriggerEvent(
                name=trigger.label,
                code=None,
                pressed=True,
                source="web",
                timestamp=time.time(),
            )
            self._last_event = f"web: {trigger.label} manual"

        try:
            self._queue.put_nowait((trigger, event))
        except queue.Full as exc:
            with self._lock:
                self._last_error = "trigger action queue is full"
            raise RuntimeError("trigger action queue is full") from exc

        return {
            "ok": True,
            "index": index,
            "trigger": trigger.label,
            "actions": len(trigger.actions),
            "message": f"Running trigger {trigger.label}.",
        }

    def handle_event(self, raw_event: Any) -> None:
        event = self._event(raw_event)
        if event is None:
            return
        aliases = self._aliases(event)
        now = time.monotonic()
        matched: List[Trigger] = []
        with self._lock:
            self._last_event = f"{event.source}: {event.name or ('BTN' + str(event.code))} {event.phase}"
            for trigger in self._definition.triggers:
                if not trigger.enabled:
                    continue
                if trigger.phase not in {"any", "change", event.phase}:
                    continue
                if not any(selector in aliases for selector in trigger.selectors):
                    continue
                if trigger.cooldown_s > 0 and now - trigger.last_fire < trigger.cooldown_s:
                    continue
                trigger.last_fire = now
                matched.append(trigger)
        for trigger in matched:
            try:
                self._queue.put_nowait((trigger, event))
            except queue.Full:
                with self._lock:
                    self._last_error = "trigger action queue is full"
                break

    def _worker(self) -> None:
        while True:
            trigger, event = self._queue.get()
            errors: List[str] = []
            try:
                # One failed sound should not suppress a later antenna/torch
                # command in the same trigger. This matches the old show daemon
                # and makes partially populated sound libraries harmless.
                for action in trigger.actions:
                    try:
                        kind = action["kind"]
                        if kind == "play":
                            self._play(action["target"], action["sound"])
                        elif kind == "play_from":
                            self._play_from(action["target"], action["directory"], bool(action.get("recursive")))
                        elif kind == "quack":
                            self._quack(action["command"])
                        elif kind == "pdplay":
                            self._pdplay(action["name"])
                        elif kind == "pdrelax":
                            self._pdrelax()
                    except Exception as exc:
                        errors.append(f"{action.get('kind', 'action')}: {type(exc).__name__}: {exc}")
                with self._lock:
                    self._fired += 1
                    self._last_trigger = trigger.label
                    self._last_error = f"{trigger.label}: " + "; ".join(errors) if errors else ""
            finally:
                self._queue.task_done()


class PuddleJoyTriggerWatcher:
    """Observe physical PuddleJoy controllers without consuming virtual FIFOs."""

    def __init__(self, callback: Callable[[Any], Any], *, discover_interval_s: float = 5.0):
        self.callback = callback
        self.discover_interval_s = max(1.0, float(discover_interval_s))
        self._controllers: Dict[str, Any] = {}
        self._input_signature: Optional[Tuple[str, ...]] = None
        self._stop = threading.Event()
        self._thread = threading.Thread(target=self._run, name="puddlejoy-triggers", daemon=True)

    def start(self) -> None:
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        for controller in list(self._controllers.values()):
            try:
                controller.close()
            except Exception:
                pass
        if self._thread.is_alive() and threading.current_thread() is not self._thread:
            self._thread.join(timeout=1.0)

    @staticmethod
    def _device_signature() -> Tuple[str, ...]:
        root = Path("/dev/input")
        if not root.is_dir():
            return ()
        paths = list(root.glob("js*")) + list(root.glob("event*"))
        return tuple(sorted(str(path) for path in paths))

    def _discover(self) -> None:
        # Drop paths udev removed. Existing Controller instances handle a
        # reconnect on the same path themselves; a new path is discovered
        # below. Keeping the map bounded also lets identical controllers return
        # after Bluetooth reconnects under a different event/js node.
        for key, controller in list(self._controllers.items()):
            device_path = str(getattr(controller, "device_path", "") or "")
            if device_path and not Path(device_path).exists():
                try:
                    controller.close()
                except Exception:
                    pass
                self._controllers.pop(key, None)

        try:
            from pd.common.puddle_joy import PuddleJoy
            found = PuddleJoy.discover(include_virtual=False)
        except Exception:
            return
        for controller in found:
            # broadcast_state observes its own virtual controllers at the
            # point where it emits their events.  A uinput-backed virtual
            # controller also appears under /dev/input, so filter by both the
            # configured device/friendly names as well as by FIFO discovery.
            virtual_names = {"PuddleDuckStick", "SteamDuckStick"}
            controller_names = {
                str(getattr(controller, "name", "") or ""),
                str(getattr(controller, "device_name", "") or ""),
            }
            if controller_names & virtual_names:
                try:
                    controller.close()
                except Exception:
                    pass
                continue
            key = str(getattr(controller, "device_path", "") or getattr(controller, "name", ""))
            if not key:
                try:
                    controller.close()
                except Exception:
                    pass
                continue
            if key in self._controllers:
                try:
                    controller.close()
                except Exception:
                    pass
                continue
            try:
                controller.set_scale(-1.0, 1.0)
            except Exception:
                pass
            self._controllers[key] = controller

    def _run(self) -> None:
        next_discovery = 0.0
        while not self._stop.is_set():
            now = time.monotonic()
            if now >= next_discovery:
                signature = self._device_signature()
                # PuddleJoy discovery opens matching event/js nodes. Avoid
                # reopening every physical controller every few seconds when
                # nothing changed; that can replay startup state and create
                # noisy connect/disconnect logs.
                if signature != self._input_signature or not self._controllers:
                    self._discover()
                    self._input_signature = signature
                next_discovery = now + self.discover_interval_s
            any_event = False
            for controller in list(self._controllers.values()):
                for _ in range(32):
                    try:
                        event = controller.read_event(blocking=False)
                    except Exception:
                        event = None
                    if event is None:
                        break
                    any_event = True
                    try:
                        self.callback(event)
                    except Exception:
                        pass
            if not any_event:
                self._stop.wait(0.01)
        for controller in list(self._controllers.values()):
            try:
                controller.close()
            except Exception:
                pass
        self._controllers.clear()
